	private void connectionCleanupCannotAbortTermMaintenance(File dataDir, boolean partialStatementStart,
			boolean asyncTermGrowth)
			throws Exception {
		var factory = SimpleValueFactory.getInstance();
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setTripleTermIndexes("spoc,cspo")
				.setForceSync(true)
				.setBulkOperationSize(0);
		IRI subject = factory.createIRI("urn:term:namespace-rollback-subject");
		TripleTerm quoted = factory.createTripleTerm(subject, PREDICATE, factory.createLiteral("live term"));
		LmdbStore seed = new LmdbStore(dataDir, config);
		seed.init();
		try {
			LmdbGcTestMaintenance.awaitPostReady(seed);
			assertTrue(seed.awaitIndexRebuild(10L, TimeUnit.SECONDS));
			try (SailConnection writer = seed.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(subject, PREDICATE, quoted);
				writer.setNamespace("stable", "urn:stable:");
				writer.commit();
			}
		} finally {
			seed.shutDown();
		}
		CountDownLatch termWriter = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		CountDownLatch applicationCancelled = new CountDownLatch(1);
		AtomicLong observedNativeId = new AtomicLong();
		CompletableFuture<Boolean> sameWriter = new CompletableFuture<>();
		AtomicReference<ValueStore> values = new AtomicReference<>();
		AtomicReference<Thread> termThread = new AtomicReference<>();
		CountDownLatch tripleStarted = new CountDownLatch(1);
		LmdbStore reopened = new LmdbStore(dataDir, config.setTripleTermIndexes("spoc,cspo,posc")) {
			@Override
			LmdbSailStore createBackingStore(File directory, StoreProperties properties,
					LmdbStoreConfig storeConfig, boolean sketches) throws IOException {
				return new LmdbSailStore(directory, properties, storeConfig, sketches,
						(valueDir, valueProperties, valueConfig) -> {
							ValueStore store = new ValueStore(valueDir, valueProperties, valueConfig) {
								@Override
								<T> T readTransaction(long environment, LmdbUtil.Transaction<T> transaction)
										throws IOException {
									return super.readTransaction(environment, (stack, txn) -> {
										if (Thread.currentThread()
												.getName()
												.equals("rdf4j-lmdb-term-index-maintenance")) {
											observedNativeId.set(mdb_txn_id(txn));
										}
										return transaction.exec(stack, txn);
									});
								}
							};
							values.set(store);
							store.setTermIndexMaintenanceObserver(phase -> {
								if (!phase.equals("dual-write-registered")) {
									return;
								}
								try {
									termThread.set(Thread.currentThread());
									store.getLmdbStats();
									long writerId = observedNativeId.get();
									long beforeMap = store.mapSizeBytes();
									termWriter.countDown();
									assertTrue(release.await(10L, TimeUnit.SECONDS));
									if (asyncTermGrowth) {
										store.reserveWriteCapacity(beforeMap + 4096L);
									}
									store.getLmdbStats();
									boolean retained = asyncTermGrowth
											? observedNativeId.get() > writerId && store.mapSizeBytes() > beforeMap
											: observedNativeId.get() == writerId;
									sameWriter.complete(retained);
									if (!retained) {
										throw new IllegalStateException("Namespace cleanup consumed the TERM writer");
									}
									if (asyncTermGrowth) {
										assertTrue(applicationCancelled.await(10L, TimeUnit.SECONDS),
												"the TERM writer must stay admitted until the waiting application is cancelled");
									}
								} catch (IOException | InterruptedException failure) {
									sameWriter.completeExceptionally(failure);
									throw new IllegalStateException(failure);
								}
							});
							return store;
						}, (tripleDir, tripleProperties, tripleConfig, tripleValues) -> new TripleStore(tripleDir,
								tripleProperties, tripleConfig, tripleValues) {
							@Override
							void startTransaction(TxnReplayPolicy.Decision decision) throws IOException {
								super.startTransaction(decision);
								if (WriterTransaction.current() != null) {
									tripleStarted.countDown();
								}
							}
						});
			}
		};
		reopened.init();
		try {
			reopened.getBackingStore().enableMultiThreading = asyncTermGrowth;
			assertTrue(termWriter.await(10L, TimeUnit.SECONDS));
			if (partialStatementStart) {
				CompletableFuture<Throwable> cancelled = new CompletableFuture<>();
				Thread writer = Thread.ofPlatform().name("partial-statement-start").unstarted(() -> {
					try (SailConnection connection = reopened.getConnection()) {
						connection.begin(IsolationLevels.SNAPSHOT);
						connection.addStatement(subject, PREDICATE, factory.createLiteral("abandoned"));
						connection.commit();
						cancelled.complete(null);
					} catch (Throwable failure) {
						cancelled.complete(failure);
					}
				});
				writer.start();
				try {
					assertTrue(tripleStarted.await(10L, TimeUnit.SECONDS),
							() -> "the statement environment must own a native writer before dictionary admission: "
									+ cancelled.getNow(null));
					long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10L);
					boolean awaitingDictionary = false;
					while (!awaitingDictionary && System.nanoTime() < deadline) {
						for (StackTraceElement frame : writer.getStackTrace()) {
							awaitingDictionary |= frame.getClassName().equals(ValueStore.class.getName())
									&& frame.getMethodName().equals("startTransaction")
									&& writer.getState() == Thread.State.WAITING;
						}
						Thread.onSpinWait();
					}
					assertTrue(awaitingDictionary, "the application must wait behind the real TERM writer");
					if (asyncTermGrowth) {
						release.countDown();
						long growthDeadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10L);
						boolean borrowedApplicationGrant = false;
						while (!sameWriter.isDone() && !borrowedApplicationGrant
								&& System.nanoTime() < growthDeadline) {
							Thread maintenance = termThread.get();
							for (StackTraceElement frame : maintenance.getStackTrace()) {
								borrowedApplicationGrant |= maintenance.getState() == Thread.State.WAITING
										&& frame.getClassName().equals(LmdbSailStore.class.getName())
										&& frame.getMethodName().equals("awaitNativeGrowthGrant");
							}
							Thread.onSpinWait();
						}
						assertFalse(borrowedApplicationGrant,
								"TERM maintenance must not await the waiting application's native growth grant");
						assertTrue(sameWriter.get(10L, TimeUnit.SECONDS),
								"the real TERM resize checkpoint must complete before the application is cancelled");
					}
					writer.interrupt();
					assertTrue(cancelled.get(10L, TimeUnit.SECONDS) instanceof SailException,
							"cancellation must fail the partial statement transaction");
				} finally {
					applicationCancelled.countDown();
					writer.interrupt();
					writer.join(10_000L);
				}
			} else {
				try (SailConnection namespace = reopened.getConnection()) {
					namespace.begin(IsolationLevels.SNAPSHOT);
					namespace.setNamespace("abandoned", "urn:abandoned:");
					namespace.prepare();
					namespace.rollback();
				}
			}
			release.countDown();
			assertTrue(sameWriter.get(10L, TimeUnit.SECONDS),
					"connection cleanup must preserve the admitted TERM native transaction ID");
			assertTrue(reopened.awaitIndexRebuild(10L, TimeUnit.SECONDS));
			assertTrue(values.get().hasTrustedReferenceCounts());
			try (SailConnection reader = reopened.getConnection();
					CloseableIteration<? extends Statement> rows = reader.getStatements(subject, PREDICATE, null,
							false)) {
				assertEquals("urn:stable:", reader.getNamespace("stable"));
				assertEquals(null, reader.getNamespace("abandoned"));
				assertTrue(rows.hasNext());
				assertEquals(quoted, rows.next().getObject());
				assertFalse(rows.hasNext());
			}
		} finally {
			release.countDown();
			applicationCancelled.countDown();
			reopened.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	@Timeout(45)
	void readOnlyRollbackOrCloseCannotAbortPostReadyRetirement(boolean close, @TempDir File dataDir)
			throws Exception {
		var factory = SimpleValueFactory.getInstance();
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true);
		IRI subject = factory.createIRI("urn:retirement:owned-post-ready-subject");
		TripleTerm quoted = factory.createTripleTerm(subject, PREDICATE, factory.createLiteral("live inner value"));
		TripleTerm nested = factory.createTripleTerm(subject, PREDICATE, quoted);
		IRI orphan = factory.createIRI("urn:retirement:owned-post-ready-orphan");
		LmdbStore seed = new LmdbStore(dataDir, config);
		seed.init();
		try {
			LmdbGcTestMaintenance.awaitPostReady(seed);
			assertTrue(seed.awaitIndexRebuild(10L, TimeUnit.SECONDS));
			try (SailConnection writer = seed.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.setNamespace("retirement", "urn:retirement:");
				writer.addStatement(subject, PREDICATE, nested);
				writer.commit();
			}
		} finally {
			seed.shutDown();
		}
		StoreProperties properties = new StoreProperties(dataDir);
		properties.load();
		ValueStore values = new ValueStore(new File(dataDir, "values"), properties, config);
		try {
			assertTrue(values.hasTrustedReferenceCounts());
			values.startTransaction(true);
			long orphanId = values.storeValue(orphan);
			long quotedId = values.getId(quoted);
			assertNotEquals(LmdbValue.UNKNOWN_ID, quotedId);
			values.recordRetiredIds(Set.of(orphanId, quotedId), 0L);
			values.commit();
			assertTrue(values.hasRetiredIds());
		} finally {
			values.close();
		}

		CountDownLatch removing = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		CompletableFuture<Long> resumedOrphanMapping = new CompletableFuture<>();
		LmdbStore reopened = new LmdbStore(dataDir, config) {
			@Override
			LmdbSailStore createBackingStore(File directory, StoreProperties storeProperties,
					LmdbStoreConfig storeConfig, boolean sketches) throws IOException {
				return new LmdbSailStore(directory, storeProperties, storeConfig, sketches,
						(valueDir, valueProperties, valueConfig) -> new ValueStore(valueDir, valueProperties,
								valueConfig) {
							@Override
							void removeRetiredIds(RetiredValueIdStore.DrainBatch batch) throws IOException {
								assertEquals(LmdbValue.UNKNOWN_ID, getId(orphan),
										"the real GC writer must already contain the uncommitted orphan deletion");
								removing.countDown();
								try {
									assertTrue(release.await(10L, TimeUnit.SECONDS));
								} catch (InterruptedException failure) {
									Thread.currentThread().interrupt();
									throw new IOException(failure);
								}
								long mapping = getId(factory.createIRI(orphan.stringValue()));
								resumedOrphanMapping.complete(mapping);
								if (mapping != LmdbValue.UNKNOWN_ID) {
									// Stop before native sizing: losing the owned writer must fail this test safely.
									throw new IOException("An unrelated connection consumed the retirement writer");
								}
								super.removeRetiredIds(batch);
							}
						}, TripleStore::new);
			}
		};
		reopened.init();
		try {
			assertTrue(removing.await(10L, TimeUnit.SECONDS));
			try (SailConnection reader = reopened.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT_READ);
				if (close) {
					reader.close();
				} else {
					reader.rollback();
				}
			}
			release.countDown();
			assertEquals(LmdbValue.UNKNOWN_ID, resumedOrphanMapping.get(10L, TimeUnit.SECONDS).longValue(),
					"read-only cleanup must preserve the PostReady writer's uncommitted retirement mapping");
			LmdbGcTestMaintenance.awaitPostReady(reopened);
			assertTrue(reopened.getBackingStore().valueStore().hasTrustedReferenceCounts());
			assertFalse(reopened.getBackingStore().hasRetiredValueIds());
			try (SailConnection reader = reopened.getConnection();
					CloseableIteration<? extends Statement> rows = reader.getStatements(subject, PREDICATE, null,
							false)) {
				assertEquals("urn:retirement:", reader.getNamespace("retirement"));
				assertTrue(rows.hasNext());
				assertEquals(nested, rows.next().getObject());
				assertFalse(rows.hasNext());
			}
		} finally {
			release.countDown();
			reopened.shutDown();
		}
		LmdbStore finalOpen = new LmdbStore(dataDir, config);
		finalOpen.init();
		try {
			LmdbGcTestMaintenance.awaitPostReady(finalOpen);
			assertTrue(finalOpen.getBackingStore().valueStore().hasTrustedReferenceCounts());
			assertEquals(LmdbValue.UNKNOWN_ID, finalOpen.getBackingStore().valueStore().getId(orphan));
			try (SailConnection reader = finalOpen.getConnection();
					CloseableIteration<? extends Statement> rows = reader.getStatements(subject, PREDICATE, null,
							false)) {
				assertEquals("urn:retirement:", reader.getNamespace("retirement"));
				assertTrue(rows.hasNext());
				assertEquals(nested, rows.next().getObject());
				assertFalse(rows.hasNext());
			}
		} finally {
			finalOpen.shutDown();
		}
	}

	@Test
	void reopenKeepsAValueReferencedByCommittedTriples(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true);
		IRI subject = SimpleValueFactory.getInstance().createIRI("urn:retirement:live-subject");
		TripleTerm quoted = SimpleValueFactory.getInstance()
				.createTripleTerm(subject, PREDICATE,
						SimpleValueFactory.getInstance().createLiteral("nested live value"));
		TripleTerm nestedQuoted = SimpleValueFactory.getInstance()
				.createTripleTerm(subject, PREDICATE, quoted);
		IRI orphan = SimpleValueFactory.getInstance().createIRI("urn:retirement:orphan-value");
		LmdbStore store = new LmdbStore(dataDir, config);
		store.init();
		try (SailConnection connection = store.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			connection.addStatement(subject, PREDICATE, nestedQuoted);
			connection.commit();
		} finally {
			store.shutDown();
		}

		StoreProperties properties = new StoreProperties(dataDir);
		properties.load();
		ValueStore valueStore = new ValueStore(new File(dataDir, "values"), properties, config);
		try {
			valueStore.startTransaction(true);
			long quotedId = valueStore.getId(quoted);
			long orphanId = valueStore.getId(orphan, true);
			assertNotEquals(LmdbValue.UNKNOWN_ID, quotedId);
			assertNotEquals(LmdbValue.UNKNOWN_ID, orphanId);
			valueStore.recordRetiredIds(Set.of(quotedId, orphanId), 0);
			valueStore.commit();
			assertTrue(valueStore.hasRetiredIds(), "retirement intents must be durable before reopening");
		} finally {
			valueStore.close();
		}

		LmdbStore reopened = new LmdbStore(dataDir, config);
		reopened.init();
		try {
			LmdbGcTestMaintenance.drainRetirements(reopened.getBackingStore());
			try (SailConnection connection = reopened.getConnection();
					CloseableIteration<? extends Statement> statements = connection.getStatements(null, null, null,
							false)) {
				assertTrue(statements.hasNext(), "the committed statement must survive retirement recovery");
				Statement statement = statements.next();
				assertEquals(subject, statement.getSubject(),
						"recovery must recheck committed triple liveness before freeing a retired quoted value ID");
				assertEquals(nestedQuoted, statement.getObject(),
						"recursive quoted values must resolve through their preserved dictionary generation");
				assertTrue(statement.getObject().isTripleTerm());
				assertEquals(quoted, ((TripleTerm) statement.getObject()).getObject());
				assertFalse(statements.hasNext());
			}
		} finally {
			reopened.shutDown();
		}

		ValueStore reopenedValueStore = new ValueStore(new File(dataDir, "values"), properties, config);
		try {
			assertEquals(LmdbValue.UNKNOWN_ID, reopenedValueStore.getId(orphan),
					"recovery should reclaim an orphaned retired value after the TripleStore liveness check");
		} finally {
			reopenedValueStore.close();
		}
	}

	@Test
	void failedTripleCommitPreservesLiveQuotedValuesAcrossReopen(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true);
		IRI subject = SimpleValueFactory.getInstance().createIRI("urn:retirement:failed-commit-subject");
		TripleTerm quoted = SimpleValueFactory.getInstance()
				.createTripleTerm(subject, PREDICATE,
						SimpleValueFactory.getInstance().createLiteral("live nested value"));
		TripleTerm nestedQuoted = SimpleValueFactory.getInstance()
				.createTripleTerm(subject, PREDICATE, quoted);
		IRI replacementSubject = SimpleValueFactory.getInstance().createIRI("urn:retirement:failed-replacement");
		FailingTripleCommitStore store = new FailingTripleCommitStore(dataDir, config);
		store.init();
		try {
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.addStatement(subject, PREDICATE, nestedQuoted);
				connection.commit();
			}

			store.failNextTripleCommit.set(true);
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.removeStatements(subject, PREDICATE, nestedQuoted);
				connection.addStatement(replacementSubject, PREDICATE,
						SimpleValueFactory.getInstance()
								.createLiteral("dictionary addition before failed triple commit"));
				SailException failure = assertThrows(SailException.class, connection::commit);
				assertTrue(failure.getCause() instanceof IOException,
						"the injected authoritative commit error should be preserved");
			}
			assertTrue(store.getBackingStore().hasRetiredValueIds(),
					"dictionary-first failure must leave its durable retirement intent for startup revalidation");
		} finally {
			store.shutDown();
		}

		LmdbStore reopened = new LmdbStore(dataDir, config);
		reopened.init();
		try {
			LmdbGcTestMaintenance.drainRetirements(reopened.getBackingStore());
			try (SailConnection connection = reopened.getConnection();
					CloseableIteration<? extends Statement> statements = connection.getStatements(null, PREDICATE, null,
							false)) {
				assertTrue(statements.hasNext(),
						"the pre-failure committed triple must remain authoritative after reopen");
				Statement statement = statements.next();
				assertEquals(subject, statement.getSubject());
				assertEquals(nestedQuoted, statement.getObject(),
						"startup retirement recovery must preserve nested values still referenced by the failed transaction's old triples");
				assertFalse(statements.hasNext(), "the failed replacement triple must not be visible");
				assertFalse(reopened.getBackingStore().hasRetiredValueIds(),
						"recovery must finish after preserving live IDs and consuming the durable intent");
			}
		} finally {
			reopened.shutDown();
		}
	}

	private static class FailingTripleCommitStore extends LmdbStore {

		private final AtomicBoolean failNextTripleCommit = new AtomicBoolean();
		private final AtomicBoolean dictionaryCommitted = new AtomicBoolean();

		private FailingTripleCommitStore(File dataDir, LmdbStoreConfig config) {
			super(dataDir, config);
		}

		@Override
		LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchBasedJoinEstimatorEnabled) throws IOException, SailException {
			return new LmdbSailStore(dataDir, properties, config, sketchBasedJoinEstimatorEnabled,
					(valueDir, valueProperties, valueConfig) -> new ValueStore(valueDir, valueProperties, valueConfig) {
						@Override
						public void commit() throws IOException {
							super.commit();
							if (failNextTripleCommit.get()) {
								dictionaryCommitted.set(true);
							}
						}
					},
					(tripleDir, tripleProperties, tripleConfig, valueStore) -> new TripleStore(tripleDir,
							tripleProperties, tripleConfig, valueStore) {
						@Override
						public void commit() throws IOException {
							if (failNextTripleCommit.compareAndSet(true, false)) {
								assertTrue(dictionaryCommitted.get(),
										"the authoritative TripleStore commit must follow the dictionary commit");
								throw new IOException("injected authoritative TripleStore commit failure");
							}
							super.commit();
						}
					});
		}
	}
